upstream mcp_fleet {
  server mcp-instance-1:8080;
  server mcp-instance-2:8080;
  server mcp-instance-3:8080;
}

server {
  location /mcp {
    proxy_pass http://mcp_fleet;
  }
}

function cachedTool(fn, ttlSeconds) {
  const store = new Map();
  return async (args) => {
    const key = JSON.stringify(args);
    const hit = store.get(key);
    if (hit && Date.now() - hit.time < ttlSeconds * 1000) {
      return hit.value;
    }
    const value = await fn(args);
    store.set(key, { value, time: Date.now() });
    return value;
  };
}
